Bash(cat ~/.claude.json 2>/dev/null | python3 -c "
import json, sys
data = json.load\(sys.stdin\)
mcps = data.get\('mcpServers', {}\)
print\(f'Total MCP servers configured: {len\(mcps\)}'\)
for name, cfg in mcps.items\(\):
    print\(f'\\n📦 {name}'\)
    for k, v in cfg.items\(\):
        if k == 'env':
            print\(f'   env: {list\(v.keys\(\)\)}'\)
        elif k == 'args' and isinstance\(v, list\):
            print\(f'   args: {v}'\)
        else:
            print\(f'   {k}: {v}'\)
")

